-- M1 slice 7: tasks (brief §8.2, D-037) and in-app notifications (FR-PLT-009); the
-- worker's reminders mark what they sent (T-059). Generated by prisma migrate diff,
-- then the checks, permissions, and data scope added by hand below.

-- CreateEnum
CREATE TYPE "TaskStatus" AS ENUM ('NEW', 'ACCEPTED', 'IN_PROGRESS', 'DONE', 'CANCELLED');

-- CreateEnum
CREATE TYPE "TaskPriority" AS ENUM ('LOW', 'NORMAL', 'HIGH');

-- AlterTable
ALTER TABLE "approval_requests" ADD COLUMN     "overdue_notified_at" TIMESTAMPTZ(3);

-- CreateTable
CREATE TABLE "tasks" (
    "id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "assigner_id" UUID NOT NULL,
    "assignee_user_id" UUID,
    "assignee_department_option_id" UUID,
    "due_at" TIMESTAMPTZ(3) NOT NULL,
    "priority" "TaskPriority" NOT NULL DEFAULT 'NORMAL',
    "status" "TaskStatus" NOT NULL DEFAULT 'NEW',
    "entity_type" TEXT,
    "entity_id" UUID,
    "accepted_at" TIMESTAMPTZ(3),
    "started_at" TIMESTAMPTZ(3),
    "done_at" TIMESTAMPTZ(3),
    "cancelled_at" TIMESTAMPTZ(3),
    "due_soon_notified_at" TIMESTAMPTZ(3),
    "overdue_notified_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "tasks_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "task_comments" (
