-- A task goes to a person or a department; once accepted, someone holds it.
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_has_assignee" CHECK ("assignee_user_id" IS NOT NULL OR "assignee_department_option_id" IS NOT NULL);
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_accepted_has_person" CHECK ("status" = 'NEW' OR "status" = 'CANCELLED' OR "assignee_user_id" IS NOT NULL);
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_entity_complete" CHECK (("entity_type" IS NULL) = ("entity_id" IS NULL));
CREATE INDEX "notifications_user_id_unread_idx" ON "notifications"("user_id") WHERE "read_at" IS NULL;

-- 09_RBAC.md: every role works and assigns tasks. Existing custom roles get them too,
-- so nobody misses a task given to them.
INSERT INTO "role_permissions" ("role_id", "permission")
SELECT r."id", p.permission FROM "roles" r CROSS JOIN (VALUES ('task.view'), ('task.create')) AS p(permission)
ON CONFLICT DO NOTHING;
-- Data scope "tasks" (D-017): Admin and Fitness Manager see every task of their
-- branches; everyone else sees what they gave, what they got, and their department's.
INSERT INTO "role_data_scopes" ("role_id", "resource", "scope")
SELECT "id", 'tasks', CASE WHEN "code" IN ('ADMIN', 'FITNESS_MANAGER') THEN 'ALL'::"DataScope" ELSE 'OWN'::"DataScope" END FROM "roles";
